// Element picking: hover to highlight, click to bind. Selectors prefer the
// stable hooks a dev controls (data-particulator, id) and say so when they
// had to fall back to something fragile.

export type PickedSelector = { selector: string; fragile: string | null };

const cssEscape = (s: string) => (typeof CSS !== "undefined" && CSS.escape ? CSS.escape(s) : s.replace(/[^a-zA-Z0-9_-]/g, "\\$&"));

/** Class names that look generated by CSS-in-JS / CSS modules (css-1x2y3z, Foo_bar__a1B2c, sc-abc123). */
const generatedClass = (c: string) => /^(css|sc|jsx|emotion)-[a-z0-9]+$/i.test(c) || /__[A-Za-z0-9]{4,}$/.test(c) || /[a-z][0-9][a-z0-9]{4,}/i.test(c) && /\d/.test(c);

const unique = (sel: string, el: Element) => {
  try {
    const all = document.querySelectorAll(sel);
    return all.length === 1 && all[0] === el;
  } catch {
    return false;
  }
};

export function selectorFor(el: Element): PickedSelector {
  const dp = el.getAttribute("data-particulator");
  if (dp) {
    const s = `[data-particulator="${dp}"]`;
    if (unique(s, el)) return { selector: s, fragile: null };
  }
  if (el.id && !/\d{3,}|:/.test(el.id)) {
    const s = `#${cssEscape(el.id)}`;
    if (unique(s, el)) return { selector: s, fragile: null };
  }
  // A stable class on the element itself?
  for (const c of Array.from(el.classList)) {
    if (generatedClass(c)) continue;
    const s = `${el.tagName.toLowerCase()}.${cssEscape(c)}`;
    if (unique(s, el)) return { selector: s, fragile: "class name (fine if it's yours and stable)" };
  }
  // Path from the nearest anchored ancestor.
  const parts: string[] = [];
  let cur: Element | null = el;
  while (cur && cur !== document.body && cur !== document.documentElement) {
    const anchor = cur.getAttribute("data-particulator")
      ? `[data-particulator="${cur.getAttribute("data-particulator")}"]`
      : cur.id && !/\d{3,}|:/.test(cur.id) ? `#${cssEscape(cur.id)}` : null;
    if (anchor && cur !== el) { parts.unshift(anchor); break; }
    const tag = cur.tagName.toLowerCase();
    const parent: Element | null = cur.parentElement;
    const sameTag = parent ? Array.from(parent.children).filter((c) => c.tagName === cur!.tagName) : [];
    parts.unshift(sameTag.length > 1 ? `${tag}:nth-of-type(${sameTag.indexOf(cur) + 1})` : tag);
    const s = parts.join(" > ");
    if (unique(s, el)) return { selector: s, fragile: "position in the page (breaks if the markup changes)" };
    cur = parent;
  }
  return { selector: parts.join(" > "), fragile: "position in the page (breaks if the markup changes)" };
}

/**
 * Start picking: highlights the element under the pointer (via onHover with its
 * rect) and resolves with the clicked element, or null on Escape. `ignore` is
 * the studio's own host element.
 */
export function pickElement(ignore: Element, onHover: (el: Element | null) => void): Promise<Element | null> {
  return new Promise((resolve) => {
    const under = (e: MouseEvent) => {
      const els = document.elementsFromPoint(e.clientX, e.clientY);
      return els.find((x) => x !== ignore && !ignore.contains(x) && !(x instanceof HTMLCanvasElement && x.dataset.particulator !== undefined) && x !== document.documentElement && x !== document.body) ?? null;
    };
    const move = (e: MouseEvent) => onHover(under(e));
    const click = (e: MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      done(under(e));
    };
    const key = (e: KeyboardEvent) => { if (e.key === "Escape") { e.preventDefault(); done(null); } };
    const block = (e: Event) => { e.preventDefault(); e.stopPropagation(); };
    function done(el: Element | null) {
      window.removeEventListener("mousemove", move, true);
      window.removeEventListener("click", click, true);
      window.removeEventListener("mousedown", block, true);
      window.removeEventListener("mouseup", block, true);
      window.removeEventListener("keydown", key, true);
      document.documentElement.style.cursor = "";
      onHover(null);
      resolve(el);
    }
    document.documentElement.style.cursor = "crosshair";
    window.addEventListener("mousemove", move, true);
    window.addEventListener("click", click, true);
    window.addEventListener("mousedown", block, true);
    window.addEventListener("mouseup", block, true);
    window.addEventListener("keydown", key, true);
  });
}
